import { keyframes } from '@emotion/react';
import styled from '@emotion/styled';

import { theme } from '../../../theme';
import type { LoadingDotsColor, LoadingDotsSize } from './LoadingDots.types';

const containerWidths: Record<LoadingDotsSize, number> = {
  medium: 16,
  large: 24,
  xlarge: 32,
  xxlarge: 40,
};

const dotSizes: Record<LoadingDotsSize, number> = {
  medium: 4,
  large: 6,
  xlarge: 8,
  xxlarge: 10,
};

const dotPulseColorful = keyframes({
  '0%, 50%, 100%': {
    backgroundColor: theme.colors.brandPrimaryBasis,
  },
  '80%': {
    backgroundColor: theme.colors.interfaceForegroundLabelSecondary,
  },
});

const dotPulseMono = keyframes({
  '0%, 50%, 100%': {
    backgroundColor: theme.colors.interfaceSurfaceSecondary,
  },
  '80%': {
    backgroundColor: theme.colors.interfaceLabelPrimary,
  },
});

interface StyledContainerProps {
  $size: LoadingDotsSize;
}

interface StyledDotProps {
  $color: LoadingDotsColor;
  $size: LoadingDotsSize;
}

export const StyledLoadingDotsContainer = styled('div')<StyledContainerProps>(
  ({ $size }) => ({
    alignItems: 'center',
    display: 'flex',
    justifyContent: 'space-between',
    minWidth: containerWidths[$size],
    width: containerWidths[$size],
  }),
);

export const StyledLoadingDot = styled('div')<StyledDotProps>(
  ({ $color, $size }) => ({
    animation: `${$color === 'colorful' ? dotPulseColorful : dotPulseMono} 0.8s infinite linear both`,
    backgroundColor: theme.colors.neutral0,
    borderRadius: '50%',
    height: dotSizes[$size],
    width: dotSizes[$size],
    '&:nth-of-type(1)': {
      animationDelay: '-0.4s',
    },
    '&:nth-of-type(2)': {
      animationDelay: '-0.2s',
    },
    '@media (prefers-reduced-motion: reduce)': {
      animation: 'none',
    },
  }),
);
